const VOCAB_API_SETTINGS=(()=>{
  const key='geneva-api-settings-v1';
  const defaults={baseUrl:'https://api.deepseek.com',model:'deepseek-flash',authMode:'auto'};
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function get(){try{const parsed=JSON.parse(localStorage.getItem(key)||'null');return parsed&&typeof parsed==='object'?{...defaults,...parsed}:defaults;}catch{return defaults;}}
  function render(){const s=get();return `<section class="card space" id="api-settings"><div><h2>模型接口设置</h2><p class="muted">默认使用 DeepSeek。API Key 只配置在服务器；此处不会保存密钥。没有 API 也能直接导入词表。</p></div><label>API 地址<input id="api-base-url" type="url" value="${escape(s.baseUrl)}" placeholder="https://api.deepseek.com" autocomplete="url"></label><p class="muted">中转地址可带 /v1；程序会自动追加 /chat/completions。中转域名需由服务器允许。</p><label>模型 ID<input id="api-model" list="api-models" value="${escape(s.model)}" placeholder="deepseek-flash"><datalist id="api-models"><option value="deepseek-flash"><option value="deepseek-v4-pro"></datalist></label><label>认证方式<select id="api-auth"><option value="auto" ${s.authMode==='auto'?'selected':''}>自动（默认 Bearer）</option><option value="bearer" ${s.authMode==='bearer'?'selected':''}>Bearer</option><option value="x-api-key" ${s.authMode==='x-api-key'?'selected':''}>x-api-key</option></select></label><button type="button" class="primary" data-action="save-api-settings">保存接口设置</button></section>`;}
  function save(){const baseUrl=document.querySelector('#api-base-url').value.trim().replace(/\/+$/,''),model=document.querySelector('#api-model').value.trim(),authMode=document.querySelector('#api-auth').value;let url;try{url=new URL(baseUrl);}catch{throw Error('请输入有效的 HTTPS API 地址');}if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||url.port)throw Error('API 地址必须是无参数的 HTTPS 地址');if(!model||model.length>120||!/^[a-zA-Z0-9._/-]+$/.test(model))throw Error('模型 ID 无效');if(!['auto','bearer','x-api-key'].includes(authMode))throw Error('认证方式无效');localStorage.setItem(key,JSON.stringify({baseUrl,model,authMode}));}
  return{get,render,save};
})();
